unsigned patch_call_insn(void *insnbuf, const void *target, u16 tgt_clobbers,
                         unsigned long addr, u16 site_clobbers, unsigned len)
{
    long delta = ((unsigned long)target) - (addr + 5);
    if (len < 5) {
        return len;
    }

    /* x86 call opcode with displacement is 0xE8 followed by 4-byte delta */
    *(unsigned char *)insnbuf = 0xE8;
    *(unsigned long *)((unsigned char *)insnbuf + 1) = delta;

    return 5;
}

unsigned patch_call_insn(void *insnbuf, const void *target, u16 tgt_clobbers,
                         unsigned long addr, u16 site_clobbers, unsigned len) {
    long delta;
    unsigned char *buf = insnbuf;

    if (len < 5) {
        // Warning: Instruction buffer is too small to patch
        return len;
    }

    delta = ((long)target) - ((long)addr + 5);

    *buf++ = 0xe8; /* opcode for call relative */
    *buf++ = delta & 0xff;
    *buf++ = (delta >> 8) & 0xff;
    *buf++ = (delta >> 16) & 0xff;
    *buf++ = (delta >> 24) & 0xff;

    return 5;
}

unsigned patch_call_insn(void *insnbuf, const void *target, u16 tgt_clobbers,
                         unsigned long addr, u16 site_clobbers, unsigned len)
{
    long delta;
    unsigned char *buf = insnbuf;

    if (len < 5) {
        /* Call instruction is too short to patch */
        return len;
    }

    delta = ((unsigned long)target - addr - 5);

    *buf = 0xff; /* opcode for call */
    *(unsigned long *)(buf + 1) = delta;

    return 5;
}
